      h2 = Math.imul(h2 ^ (c + i), 0x85ebca6b) >>> 0;
      h3 = Math.imul(h3 ^ (c ^ (i >>> 1)), 0xc2b2ae35) >>> 0;
      h4 = Math.imul(h4 ^ ((c << 3) ^ i), 0x27d4eb2d) >>> 0;
